      this.roleUser.set('');
      this.role.set('');
      this.roleError.set('');
      this.showSettings({ clerkLimit: null, floor: '', terms: '', termsA: null, termsB: null, termsC: null, latePct: '', policyDate: null, periodNumberingFrom: null, cap: null });
      this.settingsError.set('');
      if (sheet) void this.reload(sheet);
